import React, { useCallback, useEffect, useMemo, useRef } from "react";

export const useWindowWidth = () => {
  const widthRef = useRef(window.innerWidth);
  useEffect(() => {
    const onResize = () => { widthRef.current = window.innerWidth; };
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);
  return widthRef;
};

export const MenuSummary = React.memo(({ items }) => {
  const visibleItems = useMemo(() => items.filter((item) => item.visible), [items]);
  const handleSelect = useCallback((id: string) => console.info("selected", id), []);
  return (
    <ul aria-label="Menu summary">
      {visibleItems.map((item) => (
        <li key={item.id} onClick={() => handleSelect(item.id)}>{item.label}</li>
      ))}
    </ul>
  );
});

